package com.bank.account.runtime;

import java.util.logging.Logger;

// Prints the JVM's container-aware memory decisions at startup so we can SEE
// that MaxRAMPercentage and the slim-JRE/non-root choices took effect.
public class JvmMemoryReporter {
    private static final Logger log = Logger.getLogger(JvmMemoryReporter.class.getName());

    public void report() {
        Runtime rt = Runtime.getRuntime();
        long maxHeapMb = rt.maxMemory() / (1024 * 1024);   // JVM's chosen max heap
        long availableProcessors = rt.availableProcessors(); // container-aware CPU
        String user = System.getProperty("user.name");
        String javaVendor = System.getProperty("java.vendor");

        log.info(() -> "Max heap (sized by MaxRAMPercentage): " + maxHeapMb + " MB");
        log.info(() -> "Available processors (container-aware): " + availableProcessors);
        log.info(() -> "Running as user: " + user + " (must NOT be root)");
        log.info(() -> "Java vendor/runtime: " + javaVendor);

        if ("root".equals(user)) {
            log.warning(() -> "SECURITY: container is running as root — fix the Dockerfile USER directive");
        }
    }
}
