package com.bank.account;

import com.bank.account.runtime.JvmMemoryReporter;
import java.util.logging.*;

// In a real Spring Boot app this would be annotated @SpringBootApplication.
// Here it is a runnable demo that reports the exact things the Dockerfile controls.
public class AccountServiceApplication {
    private static final Logger log = Logger.getLogger(AccountServiceApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info(() -> "Starting account-service for National Bank of India");
        new JvmMemoryReporter().report();
        log.info(() -> "account-service is up — serving Rajesh (SAV2001) and Priya (CUR3001)");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
